import { Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color } from 'three/webgpu';
import { texture, uv, vec3, float, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const width = 1.9;
  const height = 1.1875; // 512:320 aspect

  const geometry = new PlaneGeometry(width, height, 1, 1);
  const material = new MeshStandardNodeMaterial({
    metalness: 0.4,
    roughness: 0.6,
  });

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = 'srgb';

  const uvNode = uv();
  const baseColor = texture(map, uvNode);

  // engineered gradient overlay: subtle vertical gradient from surface to ink
  const surfaceColor = vec3(
    float(0x0b / 255),
    float(0x0b / 255),
    float(0x10 / 255)
  );
  const inkColor = vec3(
    float(0x16 / 255),
    float(0x16 / 255),
    float(0x1d / 255)
  );

  const gradientAmount = uniform(0.12);
  const gradient = mix(surfaceColor, inkColor, uvNode.y);
  const finalColor = mix(baseColor.rgb, gradient, gradientAmount);

  material.colorNode = finalColor;
  material.opacityNode = baseColor.a;
  material.transparent = true;

  const mesh = new Mesh(geometry, material);
  mesh.position.set(3.2, -0.3, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return mesh;
}
